    }

    function test_NoInputValidationUnderflow() public {
        // Verify user starts with zero operations
        uint initialOperations = vulnerableContract.getUserOperationCount(testUser);
        assertEq(initialOperations, 0, "Initial operations should be zero");

        // Execute function with overflow-inducing input
        vm.prank(testUser);
        vulnerableContract.run(1);  // Will cause underflow since base count=0

        // Check that operation counts incremented despite underflow
        uint userOperations = vulnerableContract.getUserOperationCount(testUser);
        assertEq(userOperations, 1, "User operation count should increment");
    }

    function testFuzz_UncheckedUnderflow(uint96 input) public {
        vm.assume(input > 0);  // Only test values that can cause underflow

        // Store pre-call state
        uint preUserOperations = vulnerableContract.getUserOperationCount(testUser);

        // Execute potentially overflowing operation
        vm.prank(testUser);
        vulnerableContract.run(input);

        // Verify state updated despite underflow
        uint postUserOperations = vulnerableContract.getUserOperationCount(testUser);
        assertEq(postUserOperations, preUserOperations + 1);
    }
}
